#!/bin/bash
# Print the three most frequent IPs from access.log, most frequent first,
# breaking ties by first appearance in the log.
awk '{
    ip = $1
    if (!(ip in count)) { order[++n] = ip }
    count[ip]++
}
END {
    for (i = 1; i <= n; i++)
        printf "%d\t%d\t%s\n", count[order[i]], i, order[i]
}' access.log | sort -t $'\t' -k1,1nr -k2,2n | head -3 | cut -f3
